INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (1, 'Bateria completamente descargada o sulfatada', 'Hipotesis de falla asociada a la regla R01 (Arranque del vehiculo).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (2, 'Conexiones de bateria flojas, sulfatadas o corroidas', 'Hipotesis de falla asociada a la regla R02 (Arranque del vehiculo).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (3, 'Bateria con carga insuficiente o alternador que no recarga adecuadamente', 'Hipotesis de falla asociada a la regla R03 (Arranque del vehiculo).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (4, 'Falla en el sistema de encendido o de inyeccion al ralenti', 'Hipotesis de falla asociada a la regla R04 (Arranque del vehiculo).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (5, 'El alternador no esta generando carga', 'Hipotesis de falla asociada a la regla R05 (Arranque del vehiculo).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (6, 'Filtro de aire obstruido', 'Hipotesis de falla asociada a la regla R06 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (7, 'Sistema de admision sucio o fuga de vacio', 'Hipotesis de falla asociada a la regla R07 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (8, 'Baja presion de combustible', 'Hipotesis de falla asociada a la regla R08 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (9, 'Exceso de inyeccion de combustible (mezcla rica)', 'Hipotesis de falla asociada a la regla R09 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (10, 'Bujias o bobinas de encendido defectuosas', 'Hipotesis de falla asociada a la regla R10 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (11, 'Baja compresion o detonacion (cascabeleo)', 'Hipotesis de falla asociada a la regla R11 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (12, 'Consumo anormal de aceite por desgaste de anillos o sellos', 'Hipotesis de falla asociada a la regla R12 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (13, 'Fuga o dano en el sistema de escape', 'Hipotesis de falla asociada a la regla R13 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (14, 'Anomalia registrada por el sistema de control de emisiones', 'Hipotesis de falla asociada a la regla R14 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (15, 'Fallo de encendido severo, con riesgo de danar el catalizador', 'Hipotesis de falla asociada a la regla R15 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (16, 'Falta de lubricacion adecuada del motor', 'Hipotesis de falla asociada a la regla R16 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (17, 'Falla en el sistema de refrigeracion', 'Hipotesis de falla asociada a la regla R17 (Motor y desempeno).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (18, 'Fuga de refrigerante o falla en la bomba de agua', 'Hipotesis de falla asociada a la regla R18 (Temperatura del motor).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (19, 'Falla electrica del ventilador o de su rele', 'Hipotesis de falla asociada a la regla R19 (Temperatura del motor).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (20, 'Aire en el circuito hidraulico o fuga de liquido de frenos', 'Hipotesis de falla asociada a la regla R20 (Frenos).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (21, 'Discos de freno deformados o con desgaste irregular', 'Hipotesis de falla asociada a la regla R21 (Frenos).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (22, 'Pastillas de freno desgastadas', 'Hipotesis de falla asociada a la regla R22 (Frenos).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (23, 'Falla en un sensor de velocidad de rueda o en el modulo de ABS', 'Hipotesis de falla asociada a la regla R23 (Frenos).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (24, 'Desgaste desigual entre ejes o falla en un circuito de freno', 'Hipotesis de falla asociada a la regla R24 (Frenos).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (25, 'Falla en el sistema de direccion asistida (hidraulica o electrica)', 'Hipotesis de falla asociada a la regla R25 (Direccion).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (26, 'Desbalanceo o desgaste irregular de los neumaticos', 'Hipotesis de falla asociada a la regla R26 (Direccion).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (27, 'Desgaste en la cremallera o en los terminales de direccion', 'Hipotesis de falla asociada a la regla R27 (Direccion).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (28, 'Desgaste en el sistema de embrague', 'Hipotesis de falla asociada a la regla R28 (Transmision y tren motriz).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (29, 'Disco de embrague desgastado', 'Hipotesis de falla asociada a la regla R29 (Transmision y tren motriz).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (30, 'Nivel bajo o calidad inadecuada del liquido de transmision', 'Hipotesis de falla asociada a la regla R30 (Transmision y tren motriz).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (31, 'Desgaste o falta de lubricante en el diferencial', 'Hipotesis de falla asociada a la regla R31 (Transmision y tren motriz).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (32, 'Falla en una junta homocinetica o en el eje de transmision', 'Hipotesis de falla asociada a la regla R32 (Transmision y tren motriz).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (33, 'Conexion electrica floja o falla de masa (tierra)', 'Hipotesis de falla asociada a la regla R33 (Sistema electrico).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (34, 'Fuga de corriente en reposo o bateria en mal estado', 'Hipotesis de falla asociada a la regla R34 (Sistema electrico).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (35, 'Falla en el modulo de control electronico ECU/PCM', 'Hipotesis de falla asociada a la regla R35 (Sistema electrico).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (36, 'Amortiguadores desgastados o con fuga', 'Hipotesis de falla asociada a la regla R36 (Suspension).');
