INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (38, 'Presion baja en uno o mas neumaticos, o sensor con falla', 'Hipotesis de falla asociada a la regla R38 (Neumaticos).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (39, 'Problema de alineacion o de balanceo', 'Hipotesis de falla asociada a la regla R39 (Neumaticos).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (40, 'Bombillo fundido o fusible danado', 'Hipotesis de falla asociada a la regla R40 (Iluminacion y visibilidad).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (41, 'Falla en el motor del limpiaparabrisas o en su fusible', 'Hipotesis de falla asociada a la regla R41 (Iluminacion y visibilidad).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (42, 'Falta de gas refrigerante o compresor defectuoso', 'Hipotesis de falla asociada a la regla R42 (Climatizacion).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (43, 'Falla en la valvula de calefaccion o en el termostato del motor', 'Hipotesis de falla asociada a la regla R43 (Climatizacion).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (44, 'Falla en un sensor, en el cinturon de seguridad o en el modulo de airbag', 'Hipotesis de falla asociada a la regla R44 (Seguridad pasiva).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (45, 'Fuga de aceite por juntas, retenes o carter', 'Hipotesis de falla asociada a la regla R45 (Lubricacion del motor).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (46, 'Presion insuficiente de aceite por falla en la bomba, obstruccion o desgaste interno', 'Hipotesis de falla asociada a la regla R46 (Lubricacion del motor).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (47, 'Filtro de combustible obstruido o bomba con presion insuficiente', 'Hipotesis de falla asociada a la regla R47 (Sistema de combustible).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (48, 'Fuga en las lineas, conexiones o deposito de combustible', 'Hipotesis de falla asociada a la regla R48 (Sistema de combustible).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (49, 'Sensor MAF o MAP defectuoso o con lecturas incorrectas', 'Hipotesis de falla asociada a la regla R49 (Sensores electronicos).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (50, 'Falla intermitente del sensor de posicion del ciguenal', 'Hipotesis de falla asociada a la regla R50 (Sensores electronicos).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (51, 'Desgaste o perdida de tension en la cadena de distribucion o su tensor', 'Hipotesis de falla asociada a la regla R51 (Sistema de distribucion).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (52, 'Perdida de sincronizacion por falla de la correa o cadena de distribucion', 'Hipotesis de falla asociada a la regla R52 (Sistema de distribucion).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (53, 'Fuga en el multiple de escape, tuberias o conexiones del sistema', 'Hipotesis de falla asociada a la regla R53 (Sistema de escape y emisiones).');
