INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (55, 'Correa de accesorios desgastada, contaminada o con tension incorrecta', 'Hipotesis de falla asociada a la regla R55 (Correas y poleas).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (56, 'Polea tensora o rodamiento de polea defectuoso', 'Hipotesis de falla asociada a la regla R56 (Correas y poleas).');
