INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (59, 'Desajuste, desgaste o dano en el mecanismo del freno de estacionamiento', 'Hipotesis de falla asociada a la regla R59 (Sistema de estacionamiento).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (60, 'Falla en el actuador, interruptor o modulo electronico del sistema', 'Hipotesis de falla asociada a la regla R60 (Sistema de estacionamiento).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (61, 'Desajuste de bisagras, cerradura o mecanismo de cierre', 'Hipotesis de falla asociada a la regla R61 (Carroceria y puertas).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (62, 'Deterioro de los sellos de las puertas, ventanas o juntas de carroceria', 'Hipotesis de falla asociada a la regla R62 (Carroceria y puertas).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (63, 'Falla en el sensor de velocidad, cableado o panel de instrumentos', 'Hipotesis de falla asociada a la regla R63 (Instrumentacion y tablero).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (64, 'Falla de alimentacion electrica, fusible o modulo del cuadro de instrumentos', 'Hipotesis de falla asociada a la regla R64 (Instrumentacion y tablero).');
INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (65, 'Llave no reconocida o falla del sistema inmovilizador', 'Hipotesis de falla asociada a la regla R65 (Sistema antirrobo e inmovilizador).');
