INSERT INTO hipotesis (id_hipotesis, nombre, descripcion) VALUES (68, 'Error en sensores de rueda, modulo ABS o comunicacion electronica', 'Hipotesis de falla asociada a la regla R68 (Control de estabilidad y traccion).');
